installer-gui-script.script:
// Scripted / MDM installs: no informational alerts. Host detection is reported by the
// postinstall script (in /Library/Logs/LookMatch-install.log) and shown inline by the
// Install LookMatch app. Only a macOS that is too old stops the install.
function checkOS() {
    if (system.compareVersions(system.version.ProductVersion, '10.9') < 0) {
        my.result.type = 'Fatal';
        my.result.title = 'macOS 10.9 or later is required';
        my.result.message = 'LookMatch needs OS X 10.9 Mavericks or later.';
        return false;
    }
    return true;
}
